const dirs=[[0,-1,'↑'],[1,0,'→'],[0,1,'↓'],[-1,0,'←']];
let level=1;try{level=Number(localStorage.getItem('arrow-drift-level'))||1}catch{}level=Math.max(1,Math.min(level,999));
let size,cells,initial,lives,busy=false,seed;
const $=id=>document.getElementById(id);
function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function clearPath(index,d,board=cells){const [dx,dy]=dirs[d];let x=index%size+dx,y=Math.floor(index/size)+dy;while(x>=0&&y>=0&&x<size&&y<size){if(board[y*size+x]!==null)return false;x+=dx;y+=dy}return true}
function generate(){size=Math.min(7,5+Math.floor((level-1)/4));seed=level*9173;cells=Array(size*size).fill(0);let solution=Array(size*size).fill(null);let spots=Array.from({length:cells.length},(_,i)=>i);while(spots.length){let choices=spots.map(i=>({i,ds:dirs.map((_,d)=>d).filter(d=>clearPath(i,d))})).filter(c=>c.ds.length);let pick=choices[Math.floor(random()*choices.length)];solution[pick.i]=pick.ds[Math.floor(random()*pick.ds.length)];cells[pick.i]=null;spots.splice(spots.indexOf(pick.i),1)}initial=solution;restart()}
function restart(){busy=false;cells=[...initial];lives=3;render();$('status').textContent='Tap an arrow with a clear path to the edge.'}
function render(){const board=$('board');board.style.gridTemplateColumns=`repeat(${size},1fr)`;board.innerHTML='';cells.forEach((d,i)=>{const b=document.createElement('button');b.className='tile'+(d===null?' empty':'');b.textContent=d===null?'':dirs[d][2];b.disabled=d===null;b.setAttribute('aria-label',d===null?'Empty':`Row ${Math.floor(i/size)+1}, column ${i%size+1}, ${['up','right','down','left'][d]}`);b.onclick=()=>tap(i,b);board.append(b)});update()}
function update(){let left=cells.filter(c=>c!==null).length;$('level').textContent=`Level ${String(level).padStart(2,'0')}`;$('hearts').textContent='♥'.repeat(lives)+'♡'.repeat(3-lives);$('hearts').setAttribute('aria-label',`${lives} lives remaining`);$('remaining').textContent=`${left} LEFT`;$('progress').max=cells.length;$('progress').value=cells.length-left}
function tap(i,b){if(busy||cells[i]===null)return;document.querySelectorAll('.hint').forEach(el=>el.classList.remove('hint'));if(!clearPath(i,cells[i])){lives--;b.classList.remove('shake');void b.offsetWidth;b.classList.add('shake');$('status').textContent='Something is in the way. Try another direction.';update();if(!lives)finish(false);return}busy=true;const [dx,dy]=dirs[cells[i]];b.style.setProperty('--dx',dx*120+'px');b.style.setProperty('--dy',dy*120+'px');b.classList.add('out');cells[i]=null;update();setTimeout(()=>{busy=false;render();$('status').textContent='A little more space. Keep going.';if(cells.every(c=>c===null))finish(true)},260)}
function finish(win){busy=true;$('resultLabel').textContent=win?'BEAUTIFULLY UNTANGLED':'A FRESH PERSPECTIVE';$('result').textContent=win?'Space to breathe.':'Try a different path.';$('resultText').textContent=win?`Level ${level} complete. Your next little challenge awaits.`:'Every puzzle has a way through. Take your time.';$('continue').textContent=win?'Next puzzle →':'Try again';$('continue').onclick=()=>{$('modal').close();if(win){level++;try{localStorage.setItem('arrow-drift-level',level)}catch{}generate()}else restart()};$('modal').showModal()}
$('modal').addEventListener('cancel',e=>e.preventDefault());$('reset').onclick=()=>{if(!busy)restart()};$('hint').onclick=()=>{if(busy)return;const i=cells.findIndex((d,i)=>d!==null&&clearPath(i,d));if(i>=0){$('board').children[i].classList.add('hint');$('status').textContent='This arrow has room to move.'}};generate();

